-- Ledger содержит валидный JSON и согласованные поля envelope/payload, включая downtime.
WITH d AS (SELECT e.*,try(json_parse(event_document)) AS j,try(json_parse(payload)) AS p FROM {{target:oil_dds__event}} e) SELECT count(*) AS n FROM d WHERE j IS NULL OR p IS NULL OR event_id IS DISTINCT FROM json_extract_scalar(j,'$.event_id') OR event_type IS DISTINCT FROM json_extract_scalar(j,'$.event_type') OR entity_id IS DISTINCT FROM json_extract_scalar(j,'$.entity_id') OR entity_version IS DISTINCT FROM try_cast(json_extract_scalar(j,'$.entity_version') AS bigint) OR op IS DISTINCT FROM json_extract_scalar(j,'$.op') OR event_time IS DISTINCT FROM try(from_iso8601_timestamp_nanos(json_extract_scalar(j,'$.event_time'))) OR json_format(p) IS DISTINCT FROM json_format(json_extract(j,'$.payload')) OR load_dts IS NULL OR record_source IS NULL OR batch_id IS NULL;
